def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Final round: defect is strictly dominant.
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    # Establish a cooperative baseline early, but reciprocate obvious defection.
    if n <= 4:
        return 'C' if opp_last == 'C' else 'D'

    opp_c = 0
    recent5_def = 0

    total_mc = [0, 0]    # my action counts: 0=C, 1=D
    total_mnc = [0, 0]   # opponent cooperated next after my action
    rec_mc = [0, 0]      # recent transition counts
    rec_mnc = [0, 0]

    rec_start = n - 25
    if rec_start < 0:
        rec_start = 0

    for i in range(n):
        m, o = history[i]

        if o == 'C':
            opp_c += 1

        if i >= n - 5 and o == 'D':
            recent5_def += 1

        if i < n - 1:
            mi = 1 if m == 'D' else 0
            nxt_c = 1 if history[i + 1][1] == 'C' else 0

            total_mc[mi] += 1
            total_mnc[mi] += nxt_c

            if i >= rec_start:
                rec_mc[mi] += 1
                rec_mnc[mi] += nxt_c

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    rate = float(opp_c) / float(n)

    # Estimate how often the opponent cooperates after our C.
    if rec_mc[0] >= 3:
        qC = (float(rec_mnc[0]) + 1.0) / (float(rec_mc[0]) + 2.0)
    elif total_mc[0] >= 3:
        qC = (float(total_mnc[0]) + 1.0) / (float(total_mc[0]) + 2.0)
    else:
        qC = rate

    # Estimate how often the opponent cooperates after our D, using recent data.
    if rec_mc[1] >= 1:
        qD = (float(rec_mnc[1]) + 1.0) / (float(rec_mc[1]) + 2.0)
    else:
        qD = 0.5

    # If the opponent has been almost completely uncooperative, punish persistently.
    if opp_c <= 2 and n >= 8:
        return 'D'

    # Clear recent defection bursts against hard or mixed opponents are punished.
    if opp_last == 'D' and recent5_def >= 4 and rate < 0.72:
        return 'D'

    if opp_last == 'C' and recent5_def >= 4 and rate < 0.45:
        return 'D'

    # Exploit partners that have never punished our observed defections.
    # This discovers and exploits effectively unconditional cooperators.
    if opp_last == 'C':
        if opp_c == n and total_mc[1] >= 1 and total_mnc[1] == total_mc[1]:
            return 'D'

        # Exploit a proven forgiving response pattern while cooperation remains high.
        if rec_mc[1] >= 3 and qD >= 0.66 and rate >= 0.72 and recent5_def <= 2:
            return 'D'

    diff = qC - qD

    # If the opponent defected, decide whether to restore cooperation or punish.
    if opp_last == 'D':
        # A cooperative-looking opponent in a short punishment burst should be repaired.
        if rate >= 0.8 and recent5_def >= 4:
            return 'C'

        # If cooperation is strongly rewarded after our C, defecting is unlikely to be harmful.
        if diff >= 0.55:
            return 'C'

        # If defection is generally rewarded and cooperation is not, keep punishing.
        if diff <= 0.1:
            return 'D'

        # Occasional conciliatory tests after long punishment streaks.
        if opp_d_streak >= 4 and rate >= 0.35 and rng.random() < 0.22:
            return 'C'

        # Forgiveness for otherwise cooperative partners.
        if rate >= 0.75 and recent5_def <= 2 and rng.random() < 0.25:
            return 'C'

        return 'D'

    # Opponent cooperated: preserve mutual cooperation unless exploitation looks safe.
    if diff >= 0.55:
        return 'C'

    if diff <= 0.1:
        return 'D'

    # Light exploration against very cooperative but still-unknown opponents.
    # Limited probes are valuable for discovering forgiving types while not erasing
    # established cooperation against retaliatory types.
    if my_last == 'C' and rate >= 0.88 and total_mc[1] < 3 and recent5_def <= 1 and n < 88:
        if rng.random() < 0.07:
            return 'D'

    return 'C'
